import React,{useState} from 'react'

export default function Pizza({pizza}) {
    const [quantite, setQuantite] = useState(1);
    const [varients, setVarients] = useState('small');
    return(
        <div>
           <h1>{pizza.name}</h1>
           <img src={pizza.image} alt=''/>
           <div className='flex-container'>
            <div className='w-100'>
            <p>taille</p>
            <select value={varients} onChange={(e)=>setVarients(e.target.value)}>
                        {pizza.varients.map((varient, index) => (
                            <option key={index} value={varient}>
                                {varient}
                            </option>
                        ))}
                    </select></div>
               <div className='w-100'>
               <p>Quantité</p>
                    <input
                        type="number"
                        value={quantite}
                        onChange={(e) => setQuantite(Number(e.target.value))}
                        min={1}
                    />    </div>

                </div>
                 <div className='flex-container'>
            <div className='w-100'>
            <p>price : {pizza[0][varients] *quantite }</p>
           
           </div>
               <div className='w-100'>
             
                <input type='submit'/>
                </div>

                </div>
        
        </div>

    )
    
}
